import {deliveryMapMarkup,observeDeliveryMaps} from './delivery-map.js';
import {renderAccessNotice} from './account-access.js';
import {driverJobs,advanceJob,rejectJob,readStored} from './driver-store.js?v=2';
import {renderSettings} from './driver-settings.js';
import {renderDriverAuth} from './driver-auth.js';
import {renderDriverSupport} from './driver-support.js';
export function renderDriver(options){
  root=options.app;helpers=options.helpers;currentPath=options.segments||[];
  profile={...defaultProfile,...stored('365-driver-profile',{})};
  const page=currentPath[0]||'dashboard';if(page!=='support'&&renderAccessNotice(root,'Driver'))return;
  document.title='365 Trucking | Driver Portal';
  const api={root,shell,breadcrumb,title,panel,field,select,icon,box,notice,link,action,toggle,e,profile,stored,set,$,logo,signupDraft,toast:helpers.toast,modal:helpers.modal,go:goDriver,rerender:()=>renderDriver(options)};
  if(['login','signup','welcome','forgot','reset-sent'].includes(page))renderDriverAuth(api,page,currentPath[1]);
  else if(['profile','vehicle','payment','notifications','documents'].includes(page))renderSettings(api,page);
  else if(page==='projects')projects(currentPath[1]?decodeURIComponent(currentPath[1]):undefined);
  else if(page==='job')details(decodeURIComponent(currentPath[1]||''));
  else if(page==='earnings')earnings();
  else if(page==='earning')earningDetails(decodeURIComponent(currentPath[1]||''));
  else if(page==='support')renderDriverSupport(api);
  else dashboard();
  observeDeliveryMaps();
  root.onclick=handleDriverClick;
}
function goDriver(path){location.hash='/driver/'+path}
function handleDriverClick(event){
 const button=event.target.closest('[data-d-action]');if(!button)return;
 const value=button.dataset.value,name=button.dataset.dAction;
 const toast=helpers.toast,modal=helpers.modal;
 if(name==='menu'){const nav=$('.d-nav');nav.classList.toggle('open');button.setAttribute('aria-expanded',nav.classList.contains('open'));return}
 if(name==='account'){const existing=$('.d-account-menu');if(existing){existing.remove();button.setAttribute('aria-expanded','false');return}button.setAttribute('aria-expanded','true');button.insertAdjacentHTML('afterend',`<div class="d-account-menu">${[['Profile','profile'],['Vehicle Subscription','vehicle'],['Payment Details','payment'],['Notification Settings','notifications'],['Documents & Verification','documents'],['Support','support'],['Sign Out','login']].map(([label,path])=>`<a href="#${path==='login'?'/auth/signout':'/driver/'+path}">${label}</a>`).join('')}<a href="#/dashboard">Switch to Customer Portal</a></div>`);return}
 if(name==='advance'){
   const job=driverJobs(localStorage).find(j=>j.id===value);
   if(!job)return toast('This job is no longer available.');
   const execute=()=>{try{const status=advanceJob(localStorage,value,profile.firstName+' '+profile.lastName);details(value);toast(status==='Accepted'?'Job accepted.':status==='Completed'?'Delivery marked complete.':'Job status updated.')}catch(error){toast(error.message);details(value)}};
   if(job.status==='Picked Up')modal('Complete this delivery?','Confirm that the demo delivery has been handed over to the customer. This updates the customer order status.',execute);
   else execute();return;
 }
 if(name==='decline'){modal('Decline this job?','This hides the job for this demo driver. It does not cancel the customer booking.',()=>{try{rejectJob(localStorage,value);goDriver('projects/Pending');toast('Job declined for this driver.')}catch(error){toast(error.message)}});return}
 if(name==='save-notes'){const notes=stored('365-driver-notes',{});notes[value]=$('#d-job-notes').value;set('365-driver-notes',notes);toast('Driver notes saved locally.');return}
 if(name==='referral'){modal('Your Demo Referral Code','365-JOHN-2027 — this is a sample referral code. Bonus payments are not connected.');return}
 if(name==='receipt'){window.print();return}
 if(name==='ticket'){$('#d-ticket-form')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$('#d-name')?.focus({preventScroll:true});return}
 const messages={alerts:['Driver Notifications','No live alerts are connected. You can save notification preferences from your profile.'],call:['Customer Contact','Calls are not connected in this demo. Customer contact details in sample jobs are illustrative.'],map:['Sample Route','The map shows a sample Los Angeles route from the Figma design. Live navigation is not connected.'],chat:['Support Chat','Live support chat is not connected. Use the support ticket form to save a local demo request.'],'support-call':['Support Hotline','A verified support number has not been configured. This demo cannot place support calls.'],social:['Demo Sign-in','Google and Apple authentication are not connected. Use the demo sign-in form or Explore Driver Demo.']};
 if(messages[name])modal(...messages[name]);
}
const defaultProfile={firstName:'John',lastName:'Miller',dob:'1988-03-15',gender:'Male',license:'DL-2024-8847392',expiry:'2027-12-31',email:'john.miller@example.com',phone:'+1 (555) 123-4567',city:'Los Angeles, California',address:'1234 Sunset Boulevard, Los Angeles, CA 90028'};
let root,helpers,currentPath,profile,projectTab='Pending',pageNumber=1,query='',vehicleFilter='',dateFilter='',statusFilter='',editingProfile=false,signupDraft={};
const $=s=>root.querySelector(s);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0);
const stored=(key,fallback)=>readStored(localStorage,key,fallback);
const set=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
const icon=file=>`<span class="d-icon" aria-hidden="true"><img src="assets/driver/${file}" alt=""></span>`;
const box=(file,style='')=>`<span class="d-icon-box" ${style?`style="${style}"`:''}>${icon(file)}</span>`;
const link=(label,path,cls='')=>`<a class="btn ${cls}" href="#/driver/${path}">${label}</a>`;
const action=(label,name,value='',cls='')=>`<button type="button" class="btn ${cls}" data-d-action="${name}" data-value="${e(value)}">${label}</button>`;
const badge=status=>`<span class="d-badge ${status.toLowerCase().replaceAll(' ','-')}">${e(status)}</span>`;
const panel=(title,body,cls='')=>`<section class="d-card ${cls}"><h2>${title}</h2>${body}</section>`;
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="d-${name}">${label}</label><input id="d-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const select=(label,name,items,value,extra='')=>`<div class="field"><label for="d-${name}">${label}</label><select id="d-${name}" name="${name}" ${extra}>${items.map(x=>`<option ${value===x?'selected':''}>${e(x)}</option>`).join('')}</select></div>`;
const toggle=(name,label,on=true)=>`<label class="d-toggle"><input type="checkbox" name="${name}" aria-label="${label}" ${on?'checked':''}><span></span></label>`;
const notice=(title,body,color='',file='bfdb3.svg')=>`<aside class="d-info ${color}">${box(file)}<div><h3>${title}</h3>${body}</div></aside>`;
const breadcrumb=(title,area='Settings',path='profile')=>`<div class="d-breadcrumb"><a href="#/driver/${path}">${area}</a><span>›</span><span>${title}</span></div>`;
const title=(heading,sub)=>`<div class="d-title"><h1>${heading}</h1><p>${sub}</p></div>`;
const logo=(dark=false)=>`<a href="#/driver/dashboard" class="d-logo" aria-label="365 Trucking driver home"><img src="assets/${dark?'branding/365-trucking-updated.png':'branding/365-trucking-silver-on-red.png'}" alt="365 Trucking"></a>`;
const jobs=()=>driverJobs(localStorage).filter(j=>!stored('365-driver-declined',[]).includes(j.id));
const activeJob=()=>jobs().find(j=>['In Progress','Picked Up'].includes(j.status))||jobs().find(j=>j.status==='Accepted');
function header(active='Dashboard'){return `<header class="d-header"><div class="d-header-inner">${logo()}<nav class="d-nav" aria-label="Driver navigation">${[['Dashboard','dashboard'],['Projects','projects'],['Earnings','earnings'],['Support','support']].map(([label,path])=>`<a href="#/driver/${path}" class="${active===label?'active':''}" ${active===label?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="d-header-actions"><button type="button" data-d-action="alerts" aria-label="Driver notifications">${icon('55332.svg')}</button><button class="d-user" type="button" data-d-action="account" aria-label="Driver account menu" aria-expanded="false">${icon('29ee2.svg')}</button><button class="d-menu-toggle" type="button" data-d-action="menu" aria-label="Toggle driver navigation" aria-expanded="false">☰</button></div></div></header>`}
function footer(){return `<footer class="d-footer">© 2027 365 Trucking. All rights reserved. · <a href="#/terms">Terms</a> · <a href="#/privacy">Privacy</a><a href="#/dashboard" class="d-portal-link">Switch to Customer Portal →</a><a href="#/admin/overview" class="d-portal-link">Admin Portal →</a></footer>`}
function shell(body,{active='Dashboard',settings=false,support=false}={}){root.innerHTML=`<div class="driver-app">${header(active)}<main class="d-main ${settings?'d-settings':''} ${support?'d-support-main':''}">${body}</main>${footer()}</div>`}
function route(job){return `<div class="d-route"><div class="d-route-line">${box('0d8a7.svg')}<div><small>PICKUP</small><p>${e(job.pickup)}</p></div></div><div class="d-route-line">${box('80bb2.svg')}<div><small>DROP-OFF</small><p>${e(job.dropoff)}</p></div></div></div>`}
function jobTable(data,{compact=false}={}){return `<div class="d-table-wrap"><table class="d-table"><thead><tr>${['Project','Pickup → Drop','Date & Time',...(!compact?['Vehicle']:[]),'Amount','Status','Action'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${data.length?data.map(j=>`<tr><td><strong>#${e(j.displayId)}</strong><small>${e(j.customer)}${j.sample?'':' · Customer booking'}</small></td><td>${compact?'':icon('2561e.svg')} ${e(j.pickup)}<span class="route-drop">${icon('fe5e2.svg')} ${e(j.dropoff)}</span></td><td>${e(j.date)}<small>${e(j.time)}</small></td>${!compact?`<td>${e(j.vehicle)}</td>`:''}<td><strong>${money(j.total)}</strong></td><td>${badge(j.status)}</td><td>${link(compact?'View':'View Details','job/'+encodeURIComponent(j.id),compact?'secondary':'')}</td></tr>`).join(''):`<tr><td colspan="${compact?6:7}"><div class="d-empty">No projects match these filters.</div></td></tr>`}</tbody></table></div>`}
function dashboard(){const list=jobs(),active=activeJob(),newCompleted=list.filter(j=>!j.sample&&j.status==='Completed');const stats=[['7dd87.svg',list.filter(j=>j.status==='Pending').length,'Pending Jobs','Waiting for your response'],['36ad5.svg',list.filter(j=>j.status==='Accepted').length,'Accepted Jobs','Ready to start'],['c327b.svg',list.filter(j=>['In Progress','Picked Up'].includes(j.status)).length,'In Progress','Currently active'],['3e0df.svg',47+newCompleted.length,'Completed','Sample month + demo deliveries'],['a414e.svg',money(1245+newCompleted.reduce((a,j)=>a+j.total,0)),'Earnings This Week','Illustrative demo balance']];shell(`${title(`Welcome back, ${e(profile.firstName)}!`,"Here's an overview of your deliveries and earnings today.")}<div class="d-stats">${stats.map(s=>`<article class="d-stat">${box(s[0])}<strong>${s[1]}</strong><span>${s[2]}</span><small>${s[3]}</small></article>`).join('')}</div><section class="d-section"><h2>Quick Actions</h2><div class="d-quick-grid">${[['9331f.svg','View Pending Jobs','Check and accept new delivery requests','Open','projects/Pending',''],['3fa94.svg','Start Current Job','Begin your next scheduled delivery','Go',active?'job/'+active.id:'projects/Accepted',''],['de705.svg','Open Earnings','View your payment history and stats','Open','earnings','secondary'],['479f1.svg','Update Profile','Manage your account and vehicle info','Go','profile','secondary']].map(x=>`<article class="d-quick">${box(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p>${link(x[3],x[4],x[5])}</article>`).join('')}</div></section><section class="d-section"><h2>Active Job</h2>${active?`<article class="d-card d-active"><div><div class="d-active-title">${box('44b82.svg','background:#fef2f2')}<div><small>Project ID:　<strong>#${e(active.displayId)}</strong></small><h3>${e(active.customer)}</h3><p class="muted">${e(active.service||'Furniture delivery - 2 items')}</p></div></div>${route(active)}<p class="d-small">${icon('9e8a6.svg')}Estimated time: ${active.sample?'25 minutes':'Route estimate pending'}</p>${link('View Job Details','job/'+active.id)}</div><div class="d-status-box"><h3>Delivery Status</h3>${['On the way','Arrived','Delivered'].map((s,i)=>`<div class="d-status-item"><span class="d-status-dot ${i===0?'done':i===1?'current':''}">${i<2?icon(i===0?'8c1ce.svg':'310c0.svg'):'•'}</span>${s}</div>`).join('')}</div></article>`:`<div class="d-card d-empty"><p>You have no active job.</p>${link('View Pending Jobs','projects/Pending')}</div>`}</section><div class="d-bottom-grid"><section><h2>Recent Projects</h2><p>Your latest delivery and moving jobs.</p>${jobTable(list.filter(j=>j.status==='Completed').slice(0,5),{compact:true})}</section><section><h2>Earnings Snapshot</h2><div class="d-card">${[['Today',245],['This Week',1245],['This Month',4890]].map(x=>`<div class="d-earn-row">${box('43fcf.svg')}<span>${x[0]}</span><strong>${money(x[1])}</strong></div>`).join('')}${link('Go to Earnings','earnings','secondary')}</div></section></div><aside class="d-referral">${box('0b772.svg')}<div><h2>Earn more with referrals!</h2><p>Share your driver code and get bonuses for every successful referral.</p></div>${action('View Referral Code','referral')}</aside><p class="d-demo">Local demo: sample jobs and illustrative earnings. Customer bookings made in this browser appear under Pending.</p>`)}
function projects(tab){if(tab&&['Pending','Accepted','In Progress','Completed'].includes(tab)){projectTab=tab;pageNumber=1}const list=jobs();shell(`${title('Projects','Manage your delivery and moving jobs.')}<div class="d-tabs">${['Pending','Accepted','In Progress','Completed'].map(s=>`<a href="#/driver/projects/${encodeURIComponent(s)}" class="${s===projectTab?'active':''}">${s}<small>${list.filter(j=>s==='In Progress'?['In Progress','Picked Up'].includes(j.status):j.status===s).length}</small></a>`).join('')}</div><div class="d-filters"><input id="d-project-search" aria-label="Search projects" placeholder="Search by project or customer" value="${e(query)}"><select id="d-date-filter" aria-label="Filter by date"><option value="">All Dates</option><option value="today" ${dateFilter==='today'?'selected':''}>Today</option><option value="upcoming" ${dateFilter==='upcoming'?'selected':''}>Upcoming</option><option value="sample" ${dateFilter==='sample'?'selected':''}>Design samples</option></select><select id="d-vehicle-filter" aria-label="Filter by vehicle"><option value="">All Vehicles</option>${['Van','Truck','Pickup','Cargo Van','Box Truck','Pickup Truck','Sedan'].map(v=>`<option ${vehicleFilter===v?'selected':''}>${v}</option>`).join('')}</select><select id="d-status-filter" aria-label="Filter by source"><option value="">All Status</option><option value="customer" ${statusFilter==='customer'?'selected':''}>Customer Bookings</option><option value="sample" ${statusFilter==='sample'?'selected':''}>Sample Projects</option></select></div><div id="d-project-results"></div><p class="d-demo">Design samples are marked in project details. Declining a customer booking only hides it for this demo driver.</p>`,{active:'Projects'});function filter(){query=$('#d-project-search').value;vehicleFilter=$('#d-vehicle-filter').value;dateFilter=$('#d-date-filter').value;statusFilter=$('#d-status-filter').value;let data=jobs().filter(j=>(projectTab==='In Progress'?['In Progress','Picked Up'].includes(j.status):j.status===projectTab)&&`${j.displayId} ${j.customer} ${j.pickup} ${j.dropoff}`.toLowerCase().includes(query.toLowerCase())&&(!vehicleFilter||j.vehicle===vehicleFilter)&&(!statusFilter||(statusFilter==='sample'?j.sample:!j.sample)));const today=new Date().toLocaleDateString('en-CA');if(dateFilter==='sample')data=data.filter(j=>j.sample);if(dateFilter==='today')data=data.filter(j=>j.date===today);if(dateFilter==='upcoming')data=data.filter(j=>!j.sample&&j.date>=today);const pages=Math.max(1,Math.ceil(data.length/10));pageNumber=Math.min(pageNumber,pages);const start=(pageNumber-1)*10;$('#d-project-results').innerHTML=jobTable(data.slice(start,start+10))+`<div class="d-pagination"><span>Showing ${data.length?start+1:0}–${Math.min(start+10,data.length)} of ${data.length} projects</span><div><button type="button" class="btn outline" data-d-page="-1" ${pageNumber===1?'disabled':''}>Previous</button> <button type="button" class="btn outline" data-d-page="1" ${pageNumber===pages?'disabled':''}>Next</button></div></div>`}for(const s of ['#d-project-search','#d-date-filter','#d-vehicle-filter','#d-status-filter'])$(s).addEventListener(s.includes('search')?'input':'change',()=>{pageNumber=1;filter()});$('#d-project-results').onclick=ev=>{const b=ev.target.closest('[data-d-page]');if(b){pageNumber+=Number(b.dataset.dPage);filter()}};filter()}
function details(id){const j=driverJobs(localStorage).find(x=>x.id===id);if(!j){shell(`${title('Project Not Found','This project may no longer be available.')}${link('Back to Projects','projects')}`,{active:'Projects'});return}const steps=['Pending','Accepted','Picked Up','Delivered'],level=({Pending:0,Accepted:1,'In Progress':1,'Picked Up':2,Completed:3})[j.status]??0;const mainAction=({Pending:'Accept Job',Accepted:'Start Job','In Progress':'Mark as Picked Up','Picked Up':'Mark as Delivered'})[j.status];shell(`${breadcrumb('Project Details','Projects','projects')}${title('Project Details',`Project ID: ${e(j.displayId)}`)}<section class="d-card d-section"><h3>Status Timeline</h3><div class="d-timeline">${steps.map((s,i)=>`<div class="d-timeline-step ${i===level?'current':''}"><span class="d-status-dot ${i<level?'done':i===level?'current':''}">${icon(['bee49.svg','5ddf5.svg','2e4dd.svg','cde69.svg'][i])}</span>${s}</div>`).join('')}</div>${j.status==='Cancelled'?'<p class="d-demo">This booking was cancelled by the customer.</p>':''}</section><div class="d-detail-grid"><div class="d-stack">${panel('Job Overview',`<div class="d-overview-grid">${[['56705.svg','Customer',j.customer],['69f81.svg','Date & Time',j.date+' at '+j.time],['8184c.svg','Pickup Location',j.pickup],['2c48e.svg','Vehicle Required',j.vehicle],['951a6.svg','Drop-off Location',j.dropoff],['c22a3.svg','Estimated Distance',j.sample?'8.5 miles':'Route calculation pending'],['814f9.svg','Estimated Duration',j.sample?'25 minutes':'Route calculation pending']].map(x=>`<div class="d-overview-item">${icon(x[0])}<div><small>${x[1]}</small><p>${e(x[2])}</p></div></div>`).join('')}</div>`)}${panel('Route Map',deliveryMapMarkup({sample:j.sample,region:'driver'}))}${panel('Instructions',`<div class="d-notes-grid"><div class="d-note-panel"><h3>${icon('14690.svg')}Customer Notes</h3>${j.sample?'<ul><li>Please call upon arrival</li><li>Fragile items - handle with care</li><li>Apartment is on the 3rd floor, elevator available</li></ul>':`<p>${e(j.notes||'No special instructions.')}</p>${j.extras?.length?`<p>Extras: ${j.extras.map(x=>e(({fragile:'Fragile Items',helpers:'Extra Helpers',packing:'Packing Service'})[x]||x)).join(', ')}</p>`:''}`}</div><div class="d-note-panel yellow"><h3>${icon('c0cd7.svg')}Driver Notes</h3><textarea id="d-job-notes" aria-label="Driver Notes" rows="5" maxlength="1000">${e(stored('365-driver-notes',{})[j.id]||(j.sample?'Check parking availability before arrival. Bring moving blankets for protection.':''))}</textarea>${action('Save Notes','save-notes',j.id,'secondary')}</div></div>`)}</div><aside class="d-stack">${panel('Price Breakdown',`<div class="d-price-row"><span>Base Fare</span><strong>${money(j.sample?45:j.total)}</strong></div><div class="d-price-row"><span>Distance Fee</span><strong>${money(j.sample?Math.max(0,j.total-45):0)}</strong></div><div class="d-price-row d-price-total"><span>Total Amount</span><strong>${money(j.total)}</strong></div><div class="d-price-row"><span>Payment Status</span>${badge(j.paymentStatus||'Pending')}</div>`)}${panel('Actions',`<div class="d-action-stack">${mainAction?action(icon('aa193.svg')+' '+mainAction,'advance',j.id):`<p>${j.status==='Completed'?'This delivery is complete.':'This job is no longer available.'}</p>`}${j.status==='Pending'?action('Decline Job','decline',j.id,'outline'):''}${action(icon('f6a6b.svg')+' Call Customer','call',j.id,'outline')}${j.sample?action(icon('820d0.svg')+' Open in Maps','map',j.id,'outline'):`<a class="btn outline" href="https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(j.pickup)}&destination=${encodeURIComponent(j.dropoff)}" target="_blank" rel="noopener">${icon('820d0.svg')}Open in Maps</a>`}</div>`)}<section class="d-help"><h3>${icon('31ff6.svg')} Need Help?</h3><p>Contact our support team if you have any questions or issues with this delivery.</p>${link('Open Support','support','outline')}</section></aside></div><p class="d-demo">${j.sample?'Sample project from the Figma design. Actions only change this local demo.':'Customer booking shared in this browser. Status updates appear in the customer portal; no real dispatch is sent.'}</p>`,{active:'Projects'})}
const paidJobs=[['ORD-2024-012','Jan 13, 2025','Sarah Johnson',145,'Paid'],['ORD-2024-011','Jan 13, 2025','Michael Chen',180,'Paid'],['ORD-2024-010','Jan 12, 2025','Emily Davis',120,'Paid'],['ORD-2024-009','Jan 12, 2025','David Wilson',200,'Pending'],['ORD-2024-008','Jan 11, 2025','Lisa Anderson',165,'Paid'],['ORD-2024-007','Jan 11, 2025','James Martinez',190,'Pending'],['ORD-2024-006','Jan 10, 2025','Jennifer Taylor',155,'Paid'],['ORD-2024-005','Jan 10, 2025','Robert Brown',175,'Paid']];
function earnings(){const completed=jobs().filter(j=>!j.sample&&j.status==='Completed'),earned=completed.reduce((a,j)=>a+j.total,0);shell(`${title('Earnings','Your daily, weekly and monthly earnings.')}<div class="d-stats d-earn-stats">${[[120.5,"Today's Earnings"],[1245,'This Week'],[4890,'This Month'],[28450,'Total Earnings']].map(([n,label],i)=>`<article class="d-stat">${i===0?box('f6202.svg'):i===3?box('d4f9c.svg'):'<span class="d-icon-box"></span>'}<strong>${money(n+earned)}</strong><span>${label}</span><small>Sample balance + completed demo jobs</small></article>`).join('')}</div><div class="d-earn-layout">${panel('Earnings Overview','<p class="muted">Daily earnings for the last 30 days</p><div class="d-chart" aria-label="Illustrative daily earnings chart">'+[45,67,40,82,73,96,65,54,88,70,90,60,84,72,52,96,83,56,90,74,88,67,95,75,85,60,97,80,69,91].map((n,i)=>`<i style="height:${n}%" title="Day ${i+1}: $${n*2}"></i>`).join('')+'</div><div class="d-chart-axis"><span>Day 1</span><span>Day 10</span><span>Day 20</span><span>Day 30</span></div>','d-chart-card')}<aside class="d-payout"><h2>${icon('edbe9.svg')} Payout Info</h2><section><small>Payout Schedule</small><strong>${icon('02db0.svg')} Every Friday</strong></section><section><small>Next Payment Date</small><strong>${icon('48e20.svg')} Sample schedule</strong></section><section><small>Last Payment Amount</small><strong>${icon('e4f33.svg')} $1,180.00</strong><small>Sample payout from January 10, 2025</small></section><section><small>Payment Method</small><strong>Bank Transfer (****1234)</strong></section></aside></div><section><h2>Recent Paid Jobs</h2><p class="muted" style="margin-bottom:24px">Your latest completed or paid projects.</p><div class="d-table-wrap"><table class="d-table"><thead><tr>${['Project','Date','Customer','Amount','Payment Status','Action'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${[...completed.map(j=>[j.id,j.date,j.customer,j.total,j.paymentStatus||'Pending']),...paidJobs].map(x=>`<tr><td><strong>${e(x[0])}</strong></td><td>${e(x[1])}</td><td>${e(x[2])}</td><td><strong>${money(x[3])}</strong></td><td>${badge(x[4])}</td><td><a class="text-btn" href="#/driver/earning/${encodeURIComponent(x[0])}">View</a></td></tr>`).join('')}</tbody></table></div><div class="d-center-actions">${link('View Payment Details','payment')}</div></section><p class="d-demo">All earnings, payout schedules and payment statuses are illustrative. No real payout is processed.</p>`,{active:'Earnings'})}
function earningDetails(id){const p=paidJobs.find(x=>x[0]===id),j=driverJobs(localStorage).find(x=>x.id===id);if(!p&&!j){shell(title('Payment Not Found','Choose a job from Earnings.'),{active:'Earnings'});return}const name=p?.[2]||j.customer,total=p?.[3]||j.total;const nameInitials=name.split(' ').map(x=>x[0]).slice(0,2).join('');shell(`${breadcrumb('Job Payment Details','Earnings','earnings')}${title('Job Payment Details '+badge(j?.paymentStatus||p?.[4]||'Pending'),"Detailed breakdown of this job's delivery and payment information.")}<p class="muted" style="margin-bottom:24px">Job ID: <strong>${e(id)}</strong></p><div class="d-detail-grid"><div class="d-stack">${panel('Job Overview',`<div class="d-overview-grid"><div class="d-overview-item"><span class="d-initials" style="width:48px;height:48px;font-size:18px">${e(nameInitials)}</span><div><small>Customer</small><p>${e(name)}</p></div></div><div><small>Total Amount Earned</small><h2 style="color:#16a34a;margin:8px 0">${money(total)}</h2></div><div><small>Payment Released On</small><p>${p?'January 13, 2025 at 6:45 PM':'Pending — demo job'}</p></div><div><small>Project Type</small><p>Delivery</p></div><div><small>Vehicle Used</small><p>${e(j?.vehicle||'Cargo Van')}</p></div></div>`,'d-chart-card')}${panel('Delivery Details',`${route(j||{pickup:'1234 Downtown Storage, Main Street, Los Angeles, CA 90012',dropoff:'5678 Oak Avenue, Residential Area, Los Angeles, CA 90015'})}<div class="d-overview-grid" style="margin:24px 0"><div><small>Distance Traveled</small><p>${p?'12.5 miles':'Not recorded'}</p></div><div><small>Job Date</small><p>${e(j?.date||'January 13, 2025')}</p></div><div><small>Job Time</small><p>${e(j?.time||'2:30 PM')}</p></div><div><small>Actual Duration</small><p>${p?'1 hr 52 min':'Not recorded'}</p></div></div><div class="d-note-panel"><h3>Customer Notes</h3><p>${e(j?.notes||'Please call upon arrival. Fragile items - handle with care.')}</p></div>`)}${panel('Payment Breakdown',`${p&&p[0]==='ORD-2024-012'?[['Base Pay',45],['Mileage/Distance Pay',62.5],['Time-based Pay',18],['Heavy Item Fees',15],['Extra Stops Fees',0],['Bonuses (Peak hours, promo)',12.5],['365 Trucking Service Fee',-8]].map(x=>`<div class="d-price-row"><span>${x[0]}</span><strong>${x[1]>=0?'+':'−'}${money(Math.abs(x[1]))}</strong></div>`).join(''):`<div class="d-price-row"><span>Demo booking total</span><strong>${money(total)}</strong></div>`}<div class="d-payment-total"><strong>${p?'Final Total Paid':'Estimated Job Earnings'}</strong><strong>${money(total)}</strong></div>`)}${panel('Proof of Delivery',p?`<div class="d-proof">${['75afd.png','7f826.png','76477.png'].map((f,i)=>`<img src="assets/driver/${f}" alt="Sample proof of delivery photo ${i+1}">`).join('')}</div><div class="d-info green" style="margin:24px 0 0"><p><strong>Delivery Confirmed</strong><br>Customer confirmed delivery at 4:22 PM. Sample record.</p></div>`:'<p class="muted">No proof of delivery has been uploaded for this demo job.</p>')}</div><aside class="d-stack">${panel('Customer Info',`<h3>${e(name)}</h3><p style="color:#eab308">★★★★★ (5.0)</p><div class="d-price-row"><span>Phone Number</span><strong>(555) ***-4567</strong></div><p class="muted">Masked for privacy</p><div class="d-price-row"><span>Email Address</span><strong>s***@email.com</strong></div><div class="d-note-panel yellow"><strong>Customer Rating</strong><p>Sample customer rating for this delivery.</p></div>`)}${panel('Your Notes',`<textarea id="d-job-notes" rows="7" aria-label="Your Notes">${e(stored('365-driver-notes',{})[id]||'')}</textarea>${action('Save Notes','save-notes',id,'secondary')}<p class="d-auth-note">These notes are saved only in this browser.</p>`)}</aside></div><div class="d-form-actions">${link('← Back to Earnings','earnings','outline')}${action('Print / Save Receipt as PDF','receipt',id)}</div><p class="d-demo">Sample payment record. Print uses your browser’s Save as PDF option; it is not a tax or payment receipt.</p>`,{active:'Earnings'})}
